class Solution:
    def longestOnline(self, status: List[int], k: int) -> int:
        n, best = len(status), 0
        for i in range(n):
            zeros, j = 0, i
            while j < n and zeros + (status[j] == 0) <= k:
                zeros += status[j] == 0
                j += 1
            best = max(best, j - i)
        return best

