class Solution {
    public int longestOnline(int[] status, int k) {
        int n = status.length, best = 0;
        for (int i = 0; i < n; i++) {
            int zeros = 0, j = i;
            while (j < n && zeros + (status[j] == 0 ? 1 : 0) <= k) zeros += status[j++] == 0 ? 1 : 0;
            best = Math.max(best, j - i);
        }
        return best;
    }
}

