class Solution {
    public int longestOnline(int[] status, int k) {
        int left = 0, zeros = 0, best = 0;
        for (int i = 0; i < status.length; i++) {
            if (status[i] == 0) zeros++;
            while (zeros > k) if (status[left++] == 0) zeros--;
            best = Math.max(best, i - left + 1);
        }
        return best;
    }
}

